cat > grinder/values.py <<'PY'
"""Value types, conversions, and expression functions."""
import calendar
import datetime as dt
import json
import math
import re
from dataclasses import dataclass

MAX_INT = (1 << 63) - 1
MIN_INT = -(1 << 63)

class EvalError(Exception):
    pass

@dataclass(frozen=True)
class Date:
    ns: int

@dataclass(frozen=True)
class Duration:
    ns: int


def normalize(n):
    if isinstance(n, float) and math.isfinite(n) and n.is_integer():
        return max(MIN_INT, min(MAX_INT, int(n)))
    if type(n) is int:
        return max(MIN_INT, min(MAX_INT, n))
    return n


def from_json(v):
    if type(v) is dict:
        return {k: from_json(x) for k, x in v.items()}
    if type(v) is list:
        return [from_json(x) for x in v]
    return normalize(v)


def convert(s):
    s = s.strip()
    if s == 'true': return True
    if s == 'false': return False
    if re.fullmatch(r'[+-]?\d+', s, re.ASCII):
        i = int(s)
        if MIN_INT <= i <= MAX_INT: return i
    if re.fullmatch(r'[+-]?(?:(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?|inf(?:inity)?|nan)', s, re.I):
        try: return normalize(float(s))
        except ValueError: pass
    return s


def numeric(v):
    if type(v) in (int, float): return v
    if isinstance(v, str):
        s = ''.join(c for c in v if c in '0123456789.')
        if s:
            try: return normalize(float(s))
            except ValueError: pass
    raise EvalError('Expected number, found ' + display(v))


def boolean(v):
    if type(v) is bool: return v
    raise EvalError('Expected boolean, found ' + display(v))


def string_input(v):
    if isinstance(v, str): return v
    if v is None: raise EvalError('Found None, expected String')
    raise EvalError('Expected string, found other')


def date_string(v, json_mode=False):
    secs, frac = divmod(v.ns, 1000000000)
    try: d = dt.datetime(1970,1,1) + dt.timedelta(seconds=secs)
    except OverflowError: return str(v.ns)
    text = d.strftime('%Y-%m-%d' + ('T' if json_mode else ' ') + '%H:%M:%S')
    if frac:
        digits = 3 if frac % 1000000 == 0 else 6 if frac % 1000 == 0 else 9
        text += '.' + f'{frac:09d}'[:digits]
    return text + ('+00:00' if json_mode else ' UTC')


def duration_string(v, json_mode=False):
    sign = '-' if v.ns < 0 else ''
    ns = abs(v.ns)
    sec, frac = divmod(ns, 1000000000)
    if json_mode:
        f = ('.'+f'{frac:09d}'.rstrip('0')) if frac else ''
        return sign+'PT'+str(sec)+f+'S'
    parts = []
    for unit, size in [('d',86400000000000),('h',3600000000000),('m',60000000000),('s',1000000000),('ms',1000000),('us',1000),('ns',1)]:
        n, ns = divmod(ns, size)
        if n: parts.append(str(n)+unit)
    return sign + (''.join(parts) or '0s')


def display(v):
    if v is None: return 'None'
    if type(v) is bool: return 'true' if v else 'false'
    if type(v) is float:
        if math.isnan(v): return 'NaN'
        if math.isinf(v): return '-inf' if v < 0 else 'inf'
        return f'{v:.2f}'
    if isinstance(v, Date): return date_string(v)
    if isinstance(v, Duration): return duration_string(v)
    if isinstance(v, list): return '[' + ', '.join(display(x) for x in v) + ']'
    if isinstance(v, dict): return '{' + ', '.join(k+':'+display(v[k]) for k in sorted(v)) + '}'
    return str(v)


def rust_quote(s):
    # Rust's Debug strings have JSON-like escapes, but preserve Unicode.
    return json.dumps(str(s), ensure_ascii=False)


def debug(v):
    if v is None: return 'None'
    if type(v) is bool: return 'Bool(' + str(v).lower() + ')'
    if type(v) is int: return 'Int(' + str(v) + ')'
    if type(v) is float: return 'Float(' + plain(v) + ')'
    if isinstance(v, str): return 'Str(' + rust_quote(v) + ')'
    if isinstance(v, list): return 'Array([' + ', '.join(debug(x) for x in v) + '])'
    if isinstance(v, dict): return 'Object({' + ', '.join(rust_quote(k)+': '+debug(x) for k,x in v.items()) + '})'
    return display(v)


def plain(v):
    if isinstance(v, float):
        if math.isnan(v): return 'NaN'
        if math.isinf(v): return '-inf' if v < 0 else 'inf'
        s = str(v)
        if 'e' in s:
            s = format(v, '.15f').rstrip('0').rstrip('.') if abs(v) >= 1e-10 else s
        return s
    if isinstance(v, list): return '[' + ', '.join(debug(x) for x in v) + ']'
    if isinstance(v, dict): return '{' + ', '.join(rust_quote(k)+': '+debug(x) for k,x in v.items()) + '}'
    return display(v)


def json_value(v):
    if isinstance(v, Date): return date_string(v, True)
    if isinstance(v, Duration): return duration_string(v, True)
    if isinstance(v, float) and not math.isfinite(v): return None
    if isinstance(v, list): return [json_value(x) for x in v]
    if isinstance(v, dict): return {k: json_value(x) for k,x in v.items()}
    return v


def dump(v):
    text = json.dumps(json_value(v), ensure_ascii=False, separators=(',', ':'))
    return re.sub(r'e([+-])0+(\d+)', r'e\1\2', text)


def type_rank(v):
    if v is None: return 0
    if type(v) is bool: return 1
    if type(v) in (int, float): return 2
    if isinstance(v, Date): return 3
    if isinstance(v, Duration): return 4
    if isinstance(v, str): return 5
    if isinstance(v, list): return 6
    if isinstance(v, dict): return 7
    return 8


def compare(a,b):
    ra,rb=type_rank(a),type_rank(b)
    if ra != rb: return (ra>rb)-(ra<rb)
    if a is None: return 0
    if isinstance(a,float) and math.isnan(a): return 0 if isinstance(b,float) and math.isnan(b) else 1
    if isinstance(b,float) and math.isnan(b): return -1
    if isinstance(a, (Date,Duration)): a,b=a.ns,b.ns
    if isinstance(a, (list,dict)): return 0
    return (a>b)-(a<b)


def equal(a,b):
    if type_rank(a)!=type_rank(b): return False
    if isinstance(a,float) and math.isnan(a): return isinstance(b,float) and math.isnan(b)
    if isinstance(a,list): return len(a)==len(b) and all(equal(x,y) for x,y in zip(a,b))
    if isinstance(a,dict): return a.keys()==b.keys() and all(equal(a[k],b[k]) for k in a)
    return a==b


def freeze(v):
    if isinstance(v,list): return ('list',tuple(freeze(x) for x in v))
    if isinstance(v,dict): return ('dict',tuple((k,freeze(x)) for k,x in sorted(v.items())))
    if isinstance(v,float) and math.isnan(v): return ('num','nan')
    if type(v) in (int,float): return ('num',v)
    return (type(v).__name__, v)


def arithmetic(op,a,b):
    if isinstance(a,Date) and isinstance(b,Date) and op=='-': return Duration(a.ns-b.ns)
    if isinstance(a,Date) and isinstance(b,Duration) and op in '+-': return Date(a.ns+(b.ns if op=='+' else -b.ns))
    if isinstance(a,Duration) and isinstance(b,Date) and op=='+': return Date(a.ns+b.ns)
    if isinstance(a,Duration) and isinstance(b,Duration):
        if op in '+-': return Duration(a.ns+(b.ns if op=='+' else -b.ns))
        if op=='/': return safe_div(a.ns,b.ns)
    if isinstance(a,Duration) and type(b) in (int,float) and op in '*/':
        return Duration(int(a.ns*b if op=='*' else a.ns/b))
    if isinstance(b,Duration) and type(a) in (int,float) and op=='*': return Duration(int(a*b.ns))
    try: x,y=numeric(a),numeric(b)
    except EvalError: raise EvalError('Expected numeric operands, found '+display(a)+' '+op+' '+display(b))
    if op=='+': return normalize(x+y)
    if op=='-': return normalize(x-y)
    if op=='*': return normalize(x*y)
    if op=='/': return safe_div(x,y)


def safe_div(a,b):
    if b==0:
        if a==0: return math.nan
        return math.copysign(math.inf,a*b if b else a)
    return normalize(a/b)


def parse_date(v):
    s = plain(v).strip()
    original = s
    # Calendar timestamps accept both ISO punctuation and common written dates.
    m = re.match(r'^(\d{4})[-/](\d{1,2})[-/](\d{1,2})(?:[Tt ](\d{1,2}):(\d{2})(?::(\d{2})(?:\.(\d+))?)?)?', s)
    if m:
        y,mo,day=int(m[1]),int(m[2]),int(m[3]); h=int(m[4] or 0); mi=int(m[5] or 0); se=int(m[6] or 0)
        ns=int(((m[7] or '')+'0'*9)[:9])
        try:
            day=min(day,calendar.monthrange(y,mo)[1]); d=dt.datetime(y,mo,day,h,mi,se)
            return Date(calendar.timegm(d.timetuple())*1000000000+ns)
        except (ValueError,OverflowError):
            raise EvalError('The \'parseDate\' function failed with the error: ImpossibleTimestamp("Invalid date range given")')
    for form in ['%b %d %Y %H:%M:%S','%B %d %Y %H:%M:%S','%b %d, %Y %H:%M:%S','%b %d %Y','%B %d, %Y','%m/%d/%Y %H:%M:%S','%m/%d/%Y','%a, %d %b %Y %H:%M:%S','%d %b %Y %H:%M:%S','%Y%m%d']:
        try:
            d=dt.datetime.strptime(s,form)
            return Date(calendar.timegm(d.timetuple())*1000000000)
        except ValueError: pass
    if re.fullmatch(r'\d+',s):
        reason='InvalidNumeric('+rust_quote(s)+')' if len(s)>10 else 'ImpossibleTimestamp("Invalid date range given")'
    else:
        token=re.match(r'[A-Za-z]+',s)
        if re.match(r'\d+/[A-Za-z]+/\d+:',s): token=':'
        else: token=token[0] if token else s[:1]
        reason='UnrecognizedToken('+rust_quote(token)+')'
    raise EvalError("The 'parseDate' function failed with the error: "+reason)


MATH_FUNCTIONS = {'abs','acos','asin','atan','atan2','cbrt','ceil','cos','cosh','exp','expm1','floor','hypot','log','log10','log1p','round','sin','sinh','sqrt','tan','tanh','toDegrees','toRadians'}
FUNCTIONS=MATH_FUNCTIONS | {'concat','contains','length','now','num','parseDate','parseHex','substring','toLowerCase','toUpperCase','isNull','isEmpty','isBlank','isNumeric','if'}


def call_function(name,args):
    count={'concat':None,'substring':(2,3),'contains':2,'atan2':2,'hypot':2,'now':0}.get(name,1)
    if isinstance(count,tuple):
        if len(args) not in count: raise EvalError("The '"+name+"' function expects 2 or 3 arguments, found "+str(len(args)))
    elif count is not None and len(args)!=count:
        raise EvalError("The '"+name+"' function expects "+str(count)+" arguments, found "+str(len(args)))
    if name=='now':
        import time
        return Date(time.time_ns())
    if name=='concat': return ''.join(plain(v) for v in args)
    v=args[0]
    if name=='num': return numeric(v)
    if name=='isNull': return v is None
    if name=='isEmpty': return v is None or type(v) is str and v==''
    if name=='isBlank': return v is None or type(v) is str and v.strip()==''
    if name=='isNumeric':
        try: numeric(v);return True
        except EvalError: return False
    if name=='length': return len(v) if isinstance(v,(dict,list)) else len(plain(v))
    if name=='contains':
        if isinstance(v,list): return any(equal(x,args[1]) for x in v)
        if isinstance(v,dict): return plain(args[1]) in v
        return plain(args[1]) in plain(v)
    if name=='substring':
        offsets=[]
        for x in args[1:]:
            n=numeric(x)
            if n<0: raise EvalError('Expected positive number, found '+display(x))
            offsets.append(int(n))
        if len(offsets)==2 and offsets[1]<offsets[0]:
            raise EvalError("The 'substring' function failed with the error: end offset ("+str(offsets[1])+") is less than the start offset ("+str(offsets[0])+")")
        return plain(v)[offsets[0]:offsets[1] if len(offsets)==2 else None]
    if name=='toLowerCase': return convert(plain(v).lower())
    if name=='toUpperCase': return convert(plain(v).upper())
    if name=='parseHex':
        s=plain(v).strip()
        if s.startswith('0x'):s=s[2:]
        if re.fullmatch('[+-]?[0-9a-fA-F]+',s):
            n=int(s,16)
            if MIN_INT<=n<=MAX_INT:return n
        raise EvalError("The 'parseHex' function failed with the error: invalid hex string -- "+plain(v))
    if name=='parseDate': return parse_date(v)
    if name in MATH_FUNCTIONS:
        x=[float(numeric(v)) for v in args]
        try:
            if name=='abs': r=abs(x[0])
            elif name=='cbrt': r=math.copysign(abs(x[0])**(1/3),x[0])
            elif name=='round': r=math.copysign(math.floor(abs(x[0])+0.5),x[0])
            elif name=='toDegrees': r=math.degrees(x[0])
            elif name=='toRadians': r=math.radians(x[0])
            else: r=getattr(math,name)(*x)
        except ValueError:
            r=-math.inf if name in ('log','log10') and x[0]==0 or name=='log1p' and x[0]==-1 else math.nan
        except OverflowError: r=math.inf
        return normalize(r)
    raise EvalError('Unknown function '+name)
