@dataclass
class Expr:
    kind: str
    value: object = None
    args: list = field(default_factory=list)
    start: int = 0
    end: int = 0

@dataclass
class Op:
    kind: str
    data: dict = field(default_factory=dict)

class QueryError(Exception):
    def __init__(self, message='Failed to parse query', diagnostics=None):
        super().__init__(message)
        self.diagnostics = diagnostics or []

class Syntax(Exception):
    def __init__(self, token, message='expecting an expression'):
        self.token=token
        self.message=message


def diagnostic(query,message,start,end=None,label='',helps=(),mark='^'):
    end=start+1 if end is None else end
    start=max(0,start)
    line_no=query[:start].count('\n')+1
    base=query.rfind('\n',0,start)+1
    line=query.split('\n')[line_no-1] if line_no<=len(query.split('\n')) else ''
    col=start-base
    count=max(1,end-start)
    # The compact source excerpt follows the terminal diagnostic convention.
    gutter=' ' * (len(str(line_no))+1)
    text='error: '+message+'\n'+gutter+'|\n'+str(line_no)+' | '+line+'\n'+gutter+'| '+' '*col+mark*count
    if label:text+=' '+label
    text+='\n'+gutter+'|\n'
    for h in helps:text+='  = help: '+h+'\n'
    return text


