    def take(self):t=self.peek();self.i+=1;return t
    def parse(self):
        if not self.tokens:return ('all',)
        try:return self.or_expr()
        except (IndexError,ValueError):
            start=self.tokens[min(self.i,len(self.tokens)-1)][1]
            raise QueryError(diagnostics=[diagnostic(self.query,'expecting a search term',start,len(self.text))])
    def or_expr(self):
        left=self.and_expr()
        while self.peek()=='OR':
            self.take();left=('or',left,self.and_expr())
        return left
    def and_expr(self):
        left=self.atom()
        while self.peek() and self.peek() not in (')','OR'):
            if self.peek()=='AND':self.take()
            left=('and',left,self.atom())
        return left
    def atom(self):
        t=self.take()
        if not t:raise ValueError()
        if t=='NOT':return ('not',self.atom())
        if t=='(':
            e=self.or_expr()
            if self.take()!=')':raise ValueError()
            return e
        if t=='*':return ('all',)
        if t[0] in '\"\'':
            value=lex(t)[0].value
            return ('literal',value)
        try:return ('pattern',re.compile('.*'.join(re.escape(x) for x in t.split('*')),re.I))
        except re.error:return ('literal',t)
