"""Execution of streaming transformations and grouped computations."""
import collections
import functools
import itertools
import json
import math
import re
import sys
from dataclasses import dataclass, field
from .parser import root_name
from .values import *

@dataclass
class Row:
    raw: str = ''
    fields: dict = field(default_factory=dict)
    parsed: bool = False


def evaluate(expr,row):
    kind=expr.kind
    if kind=='lit':return expr.value
    if kind=='field':
        if expr.value not in row.fields:raise EvalError('No value for key '+rust_quote(expr.value))
        return row.fields[expr.value]
    if kind=='get':
        val=evaluate(expr.args[0],row)
        if not isinstance(val,dict):raise EvalError('Expected object, found '+display(val))
        if expr.value not in val:raise EvalError('No value for key '+rust_quote(expr.value))
        return val[expr.value]
    if kind=='index':
        val=evaluate(expr.args[0],row)
        if not isinstance(val,list):raise EvalError('Expected array, found '+display(val))
        if not -len(val)<=expr.value<len(val):raise EvalError('Index '+str(expr.value)+' out of range')
        return val[expr.value]
    if kind=='not':return not boolean(evaluate(expr.args[0],row))
    if kind=='bin':
        a=evaluate(expr.args[0],row);op=expr.value
        if op in ('and','&&'):return boolean(a) and boolean(evaluate(expr.args[1],row))
        if op in ('or','||'):return boolean(a) or boolean(evaluate(expr.args[1],row))
        b=evaluate(expr.args[1],row)
        if op in '+-*/':return arithmetic(op,a,b)
        if op=='==':return equal(a,b)
        if op in ('!=','<>'):return not equal(a,b)
        c=compare(a,b)
        return {'>':c>0,'>=':c>=0,'<':c<0,'<=':c<=0}[op]
    if kind=='call':
        if expr.value=='if':
            test=boolean(evaluate(expr.args[0],row))
            return evaluate(expr.args[1] if test else expr.args[2],row)
        return call_function(expr.value,[evaluate(x,row) for x in expr.args])
    raise EvalError('Expected valid expr, found value expr')


def assign_path(expr,row,value):
    if expr is None:
        row.fields['_split']=value;return
    if expr.kind=='field':row.fields[expr.value]=value;return
    if expr.kind=='get':
        parent=evaluate(expr.args[0],row)
        if not isinstance(parent,dict):raise EvalError('Expected object, found '+display(parent))
        parent[expr.value]=value;return
    if expr.kind=='index':
        parent=evaluate(expr.args[0],row)
        if not isinstance(parent,list):raise EvalError('Expected array, found '+display(parent))
        if not -len(parent)<=expr.value<len(parent):raise EvalError('Index '+str(expr.value)+' out of range')
        parent[expr.value]=value;return
    raise EvalError('Expected valid expr, found value expr')


def matches(filt,line):
    kind=filt[0]
    if kind=='all':return True
    if kind=='literal':return filt[1] in line
    if kind=='pattern':return filt[1].search(line) is not None
    if kind=='and':return matches(filt[1],line) and matches(filt[2],line)
    if kind=='or':return matches(filt[1],line) or matches(filt[2],line)
    if kind=='not':return not matches(filt[1],line)
    return False


