    groups={};d=op.data
    for row in rows:
        key=[]
        for expr in d['groups']:
            try:key.append(evaluate(expr,row))
            except EvalError:key.append(None)
        fkey=tuple(freeze(x) for x in key)
        if fkey not in groups:
            groups[fkey]=(key,[{'count':0,'sum':0,'nums':[],'distinct':set()} for a in d['aggs']])
        states=groups[fkey][1]
