"""Legacy tables, JSON records, logfmt, and named string formatting."""
import re
from .values import display,dump

class FormatError(Exception):pass


def width(s):
    return len(s.encode('utf-8'))

class Aligner:
    def __init__(self):self.columns=[];self.widths={}
    def add(self,key,text):
        n=width(text)
        if key not in self.widths:
            self.columns.append(key);self.widths[key]=n+8
        elif self.widths[key]-n<4:self.widths[key]=n+8
    def row(self,row):
        if not row.parsed and not row.fields:return row.raw+'\n'
        fields={k:'['+k+'='+display(v)+']' for k,v in row.fields.items()}
        for k in sorted(fields):self.add(k,fields[k])
        text='';padding=0
        for k in self.columns:
            if k in fields:
                if text:text+=' '*padding
                text+=fields[k];padding=self.widths[k]-width(fields[k])
            elif text:padding+=self.widths[k]
        return text+'\n'

class NamedFormat:
    def __init__(self,text):
        self.parts=[];i=0;literal=''
        while i<len(text):
            if text[i:i+2] in ('{{','}}'):
