def evaluate(expr,row):
    kind=expr.kind
    if kind=='lit':return expr.value
    if kind=='field':
        if expr.value not in row.fields:raise EvalError('No value for key '+rust_quote(expr.value))
        return row.fields[expr.value]
    if kind=='get':
        val=evaluate(expr.args[0],row)
        if not isinstance(val,dict):raise EvalError('Expected object, found '+display(val))
        if expr.value not in val:raise EvalError('No value for key '+rust_quote(expr.value))
        return val[expr.value]
    if kind=='index':
        val=evaluate(expr.args[0],row)
        if not isinstance(val,list):raise EvalError('Expected array, found '+display(val))
        if not -len(val)<=expr.value<len(val):raise EvalError('Index '+str(expr.value)+' out of range')
        return val[expr.value]
    if kind=='not':return not boolean(evaluate(expr.args[0],row))
    if kind=='bin':
